/// Bytes of every column for a pool of `n` envs.
pub const fn col_bytes(n: usize) -> [usize; N_COLUMNS] {
    let mut out = [0usize; N_COLUMNS];
    let mut i = 0;
    while i < N_COLUMNS {
        let c = COLUMNS[i];
        out[i] = c.row_elems * c.dtype.size() * if c.per_env { n } else { 1 };
        i += 1;
    }
    out
}

